from concurrent.futures import ProcessPoolExecutor
import multiprocessing
pred=sys.modules['predict_mast']
original_predict=pred.predict_shot
def logged_predict(path,*args,**kwargs):
 result=original_predict(path,*args,**kwargs)
 print(json.dumps({'shot_done':Path(path).stem,'solved':result.solved}),file=sys.stderr,flush=True)
 return result
pred.predict_shot=logged_predict
import os
paths=sorted(Path(os.environ['MAST_SPLIT_DIR']).glob('*.parquet'))
assert len(paths)>=1
bounds=np.linspace(0,len(paths),min(32,len(paths))+1).astype(int)
runs=[paths[a:b] for a,b in zip(bounds[:-1],bounds[1:]) if b>a]
results=[]
with ProcessPoolExecutor(max_workers=8,mp_context=multiprocessing.get_context('fork')) as pool:
 for part in pool.map(pred._predict_many,runs):results.extend(part)
results=pred._with_mean_pattern_where_nothing_solved(paths,results)
fallback=(float(np.nanmedian(np.concatenate([r.q95 for r in results]))),float(np.nanmedian(np.concatenate([r.beta_n for r in results]))))
assert np.isfinite(fallback).all()
archive=pred.PredictionArchive()
for result in results:
 assert np.isfinite(result.maps).all()
 archive.add(result.maps,np.where(np.isfinite(result.q95),result.q95,fallback[0]),np.where(np.isfinite(result.beta_n),result.beta_n,fallback[1]))
assert archive.shots==len(paths) and archive.replaced==0 and not blocked
np.savez_compressed(sys.stdout.buffer,allow_pickle=False,**archive._entries)
sys.stdout.buffer.flush()
print(json.dumps({'status':'archive_stream_complete','shots':archive.shots,'frames':archive.frames,'solved_frames':sum(r.solved for r in results),'fallback':fallback,'forbidden_mask_reads':blocked,'per_shot':[[Path(f).stem,int(r.maps.shape[0]),r.solved,r.q95_read,r.beta_n_read] for f,r in zip(paths,results)]}),file=sys.stderr,flush=True)
